{
  "name": "@dietrichgebert/ponytail",
  "version": "4.9.0",
  "description": "Lazy senior dev mode for AI agents. The best code is the code you never wrote.",
  "keywords": ["opencode-plugin", "opencode", "ponytail", "pi-package", "pi", "skills", "qoder"],
  "license": "MIT",
  "author": {
    "name": "Dietrich Gebert",
    "url": "https://github.com/DietrichGebert"
  },
  "homepage": "https://github.com/DietrichGebert/ponytail",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/DietrichGebert/ponytail.git"
  },
  "bugs": {
    "url": "https://github.com/DietrichGebert/ponytail/issues"
  },
  "main": "./.opencode/plugins/ponytail.mjs",
  "exports": {
    ".": "./.opencode/plugins/ponytail.mjs",
    "./plugin": "./.opencode/plugins/ponytail.mjs"
  },
  "files": [
    "AGENTS.md",
    "hooks/",
    "skills/",
    ".opencode/",
    ".qoder/",
    ".qoder-plugin/",
    "pi-extension/",
    "scripts/uninstall.js",
    "assets/",
    "LICENSE"
  ],
  "scripts": {
    "test": "node --test tests/*.test.js && npm test --prefix pi-extension && npm test --prefix ponytail-mcp"
  },
  "pi": {
    "extensions": ["./pi-extension/index.js"],
    "skills": ["./skills"]
  },
  "publishConfig": {
    "access": "public"
  }
}

{
  "name": "opencode-mem",
  "version": "2.25.0",
  "description": "OpenCode plugin that gives coding agents persistent memory using local Turso/libSQL vector search",
  "type": "module",
  "main": "dist/plugin.js",
  "types": "dist/index.d.ts",
  "exports": {
    ".": {
      "import": "./dist/plugin.js",
      "types": "./dist/index.d.ts"
    },
    "./server": {
      "import": "./dist/plugin.js",
      "types": "./dist/index.d.ts"
    },
    "./tags": {
      "import": "./dist/services/tags.js",
      "types": "./dist/services/tags.d.ts"
    }
  },
  "scripts": {
    "build": "rm -rf dist && bunx tsc && bun run web:build",
    "web:dev": "cd web && bun run dev",
    "web:build": "cd web && bun run build",
    "dev": "tsc --watch",
    "test": "bun test",
    "typecheck": "tsc --noEmit",
    "format": "prettier --write \"src/**/*.{ts,css,html}\" \"web/src/**/*.{ts,tsx,css,html}\"",
    "format:check": "prettier --check \"src/**/*.{ts,css,html}\" \"web/src/**/*.{ts,tsx,css,html}\"",
    "prepare": "husky"
  },
  "keywords": [
    "opencode",
    "plugin",
    "memory",
    "vector-database",
    "ai",
    "coding-agent",
    "local",
    "standalone"
  ],
  "author": "opencode-mem",
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/tickernelz/opencode-mem.git"
  },
  "publishConfig": {
    "access": "public"
  },
  "dependencies": {
    "@huggingface/transformers": "^4.2.0",
    "@libsql/client": "^0.17.4",
    "@opencode-ai/plugin": "^1.18.15",
    "@opencode-ai/sdk": "^1.18.15",
    "franc-min": "^6.2.0",
    "hono": "^4.12.32",
    "iso-639-3": "^3.0.1",
    "onnxruntime-node": "1.20.1",
    "zod": "^4.4.3"
  },
  "//": "Pin onnxruntime-node@1.20.1 (direct + override): nested OpenCode installs ignore package overrides (#184); 1.21.0–1.23.2 can SIGILL on macOS process exit (#225); fixed releases still lack darwin/x64 (microsoft/onnxruntime#27961).",
  "overrides": {
    "onnxruntime-node": "1.20.1",
    "bun-types": "1.3.14"
  },
  "devDependencies": {
    "@types/bun": "^1.4.0",
    "husky": "^9.1.7",
    "lint-staged": "^17.3.0",
    "prettier": "^3.9.6",
    "typescript": "7.0.2"
  },
  "opencode": {
    "type": "plugin",
    "hooks": [
      "chat.message",
      "event"
    ]
  },
  "files": [
    "dist",
    "package.json"
  ],
  "lint-staged": {
    "*.{ts,tsx,css,html,json,md}": [
      "prettier --write"
    ]
  }
}

[workspace]
resolver = "2"
members = [
  "devenv",
  "devenv-activity",
  "devenv-activity-macros",
  "devenv-cache-core",
  "devenv-core",
  "devenv-eval-cache",
  "devenv-event-sources",
  "devenv-nix-backend",
  "devenv-nix-backend-macros",
  "devenv-processes",
  "devenv-mailbox",
  "devenv-reload",
  "devenv-run-tests",
  "devenv-shell",
  "devenv-snix-backend",
  "devenv-tasks",
  "devenv-tui",
  "nix-conf-parser",
  "tokio-shutdown",
  "xtask",
]

[workspace.package]
version = "2.2.3"
edition = "2024"
license = "APACHE-2.0"
homepage = "https://devenv.sh/"
repository = "https://github.com/cachix/devenv/"

[workspace.dependencies]
devenv = { path = "devenv" }
devenv-activity = { path = "devenv-activity" }
devenv-activity-macros = { path = "devenv-activity-macros" }
devenv-core = { path = "devenv-core" }
devenv-eval-cache = { path = "devenv-eval-cache" }
devenv-event-sources = { path = "devenv-event-sources" }
devenv-processes = { path = "devenv-processes" }
devenv-mailbox = { path = "devenv-mailbox" }
devenv-snix-backend = { path = "devenv-snix-backend" }
devenv-nix-backend = { path = "devenv-nix-backend" }
devenv-nix-backend-macros = { path = "devenv-nix-backend-macros" }
devenv-tasks = { path = "devenv-tasks" }
devenv-tui = { path = "devenv-tui" }
devenv-reload = { path = "devenv-reload" }
devenv-shell = { path = "devenv-shell" }
devenv-cache-core = { path = "devenv-cache-core" }
nix-conf-parser = { path = "nix-conf-parser" }
tokio-shutdown = { path = "tokio-shutdown" }

nix-bindings-flake = { git = "https://github.com/cachix/nix-bindings-rust.git", branch = "2.34" }
nix-bindings-expr = { git = "https://github.com/cachix/nix-bindings-rust.git", branch = "2.34" }
nix-bindings-store = { git = "https://github.com/cachix/nix-bindings-rust.git", branch = "2.34" }
nix-bindings-util = { git = "https://github.com/cachix/nix-bindings-rust.git", branch = "2.34" }
nix-bindings-fetchers = { git = "https://github.com/cachix/nix-bindings-rust.git", branch = "2.34" }
nix-cmd = { git = "https://github.com/cachix/nix-bindings-rust.git", branch = "2.34" }
nix-bindings-bindgen-raw = { git = "https://github.com/cachix/nix-bindings-rust.git", branch = "2.34" }

libghostty-vt = { git = "https://github.com/Uzaaft/libghostty-rs.git", branch = "master" }
libghostty-vt-sys = { git = "https://github.com/Uzaaft/libghostty-rs.git", branch = "master", default-features = false, features = [
  "pkg-config",
] }
base64 = "0.22"
anyhow = "1.0.102"
async-priority-channel = "0.2.0"
async-trait = "0.1"
# Pinned to 1.8.3: blake3 1.8.4 upgraded to digest 0.11 which is incompatible
# with snix-castore (uses digest 0.10 APIs).
blake3 = "=1.8.3"
chrono = { version = "0.4", features = ["serde"] }
clap = { version = "4.6.1", features = ["derive", "cargo", "env"] }
clap_complete = { version = "4.6.3", features = ["unstable-dynamic"] }
clap_mangen = "0.3.0"
cstr = "0.2"
cli-table = "0.5.0"
console = "0.16.3"
detect-coding-agent = "0.1.0"
dialoguer = "0.12.0"
dotenv = { package = "dotenv-ng", version = "1.0.0" }
fd-lock = "4"
futures = "0.3.32"
hex = "0.4.3"
hostname = "0.4.2"
humantime = "2"
include_dir = "0.7.4"
indexmap = "2.14.0"
indoc = "2.0.7"
pathdiff = "0.2.3"
miette = { version = "7.6.0", features = ["fancy"] }
nix = { version = "0.31", features = ["fs", "poll", "process", "resource", "signal", "term"] }
nix-flake-lock = "0.1.0"
num_enum = "0.7"
once_cell = "1.21.4"
petgraph = "0.8.3"
pretty_assertions = { version = "1.4.1", features = ["unstable"] }
netstat2 = "0.11"
regex = "1.12.3"
schemars = "1.2.1"
schematic = { version = "0.19", features = [
  "schema",
  "yaml",
  "renderer_template",
  "renderer_json_schema",
] }
secrecy = "0.10"
# https://github.com/mikaelmello/inquire/pull/330
secretspec = { git = "https://github.com/cachix/secretspec", tag = "v0.19.1" }
semver = "1"
serde = { version = "1.0.228", features = ["derive"] }
# default-features = false drops the `reqwest` feature (remote https
# imports); we only read a local cachix config and want no network stack.
serde_dhall = { version = "0.13.0", default-features = false }
serde_json = "1.0.149"
serde_repr = "0.1.20"
serde_with = "3"
serde_yaml = "0.9.34"
ser_nix = "0.2.4"
similar = "3.1.0"
sha2 = "0.11.0"
shell-escape = "0.1.5"
sqlx = { version = "0.9.0", features = ["time", "sqlite", "runtime-tokio"] }
strum = { version = "0.28", features = ["derive"] }
tempfile = "3.27.0"
termimad = "0.34"
tokio-test = "0.4"
thiserror = "2.0.18"
tracing = { version = "0.1.44", features = ["valuable"] }
tracing-subscriber = { version = "0.3.23", features = [
  "env-filter",
  "json",
  "valuable",
] }
valuable = { version = "0.1", features = ["derive"] }
json-subscriber = { version = "0.2.8" }
tokio = { version = "1.52.1", features = [
  "process",
  "fs",
  "io-util",
  "macros",
  "rt-multi-thread",
  "sync",
  "time",
] }
tokio-util = { version = "0.7.18", features = ["io"] }
tokio-stream = "0.1"
uuid = { version = "1.23", features = ["v4"] }
which = "8.0.2"
whoami = "2.1.2"
xdg = "3.0.0"
